// Unit tests for lib.js - run them with:  node --test
// Do not edit this file.
import { afterEach, describe, test } from "node:test";
import assert from "node:assert/strict";
import { loadSongs, needsPractice, withPractised, countByInstrument, byTitle } from "../lib.js";

// A stand-in for fetch(): answers with the given status and JSON body.
function fakeFetch(status, body) {
  return async () => ({
    ok: status >= 200 && status < 300,
    status,
    json: async () => {
      if (status !== 200) throw new SyntaxError("Unexpected token '<'");
      return body;
    },
    text: async () => JSON.stringify(body),
  });
}

const sample = () => [
  { title: "Hey Jude", instrument: "piano", practiceEvery: 3, daysSincePractised: 3 },
  { title: "Africa", instrument: "drums", practiceEvery: 20, daysSincePractised: 4 },
  { title: "Creep", instrument: "piano", practiceEvery: 5, daysSincePractised: 6 },
];

describe("Bug 1 - loadSongs", () => {
  const realFetch = globalThis.fetch;
  const realError = console.error;
  afterEach(() => {
    globalThis.fetch = realFetch;
    console.error = realError;
  });

  test("resolves to the parsed array when the response is OK", async () => {
    globalThis.fetch = fakeFetch(200, sample());
    assert.deepEqual(await loadSongs(), sample());
  });

  test("rejects with 'HTTP 404' when the file is missing", async () => {
    globalThis.fetch = fakeFetch(404, []);
    console.error = () => {};
    await assert.rejects(loadSongs(), { message: "HTTP 404" });
  });

  test("rejects with 'HTTP 500' when the server fails", async () => {
    globalThis.fetch = fakeFetch(500, []);
    console.error = () => {};
    await assert.rejects(loadSongs(), { message: "HTTP 500" });
  });
});

describe("Bug 2 - needsPractice", () => {
  test("includes a song that is due today", () => {
    assert.ok(needsPractice(sample()).some((song) => song.title === "Hey Jude"));
  });

  test("keeps exactly the songs that need practice", () => {
    assert.deepEqual(needsPractice(sample()), [sample()[0], sample()[2]]);
  });

  test("does not change the songs", () => {
    const songs = sample();
    needsPractice(songs);
    assert.deepEqual(songs, sample());
  });
});

describe("Bug 3 - withPractised", () => {
  test("sets that song's daysSincePractised to 0", () => {
    const creep = withPractised(sample(), "Creep").find((song) => song.title === "Creep");
    assert.equal(creep.daysSincePractised, 0);
  });

  test("leaves the other songs as they were", () => {
    const result = withPractised(sample(), "Creep");
    assert.deepEqual(result.slice(0, 2), sample().slice(0, 2));
  });

  test("returns a new array", () => {
    const songs = sample();
    assert.notEqual(withPractised(songs, "Creep"), songs);
  });

  test("does not change the original songs", () => {
    const songs = sample();
    withPractised(songs, "Creep");
    assert.deepEqual(songs, sample());
  });
});

describe("Bug 4 - countByInstrument", () => {
  test("counts the songs for each instrument", () => {
    assert.deepEqual(countByInstrument(sample()), { piano: 2, drums: 1 });
  });

  test("is {} for an empty list", () => {
    assert.deepEqual(countByInstrument([]), {});
  });
});

describe("Bug 5 - byTitle", () => {
  test("sorts by title, A to Z", () => {
    assert.deepEqual(byTitle(sample()).map((song) => song.title), ["Africa", "Creep", "Hey Jude"]);
  });

  test("returns a new array", () => {
    const songs = sample();
    assert.notEqual(byTitle(songs), songs);
  });

  test("does not reorder the list it was given", () => {
    const songs = sample();
    byTitle(songs);
    assert.deepEqual(songs, sample());
  });
});
